INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1198557-chem311', 'stk-chemist', 'CHEM 311', 'info', '{"desc": "من أروع مواد الكيمياء التي مرت علي\nالمنهج سهل مو صعب وخاصه تشابتر 9 أروع تشابتر\nالمنهج يغطي الكيمياء الكهربائية ان صح التعبير (Ch 7 & 8) وانواع التفاعلات وقوانينها وكيفية كتابة Reaction Rate Law\n( Ch 9 & 10) و Absorpton & Adsorbtion وViscosity , Diffusion Ch 18 & 19\n\nLab\nممل وطويل على غير صنع 😐 واحس مافيه ترابط قوي بين ماتدرسه وبين اللاب أحس الاب تضيع وقت وتعذيب لطالب أحس انهم تعمقوا في التجارب كثير.\n\nCHEM 311 مهمة جدا مو مثل 201 و 202 CHE 402 أوائل المادة والماتيريال تبع ميجر ون كله يعتمد على 311 بشكل كبير يعني اتعب في 311 ارتاح في 402\n\nسلام 🤴", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-311-physical-chemistry-ii/120596/5", "user": "Chemist", "ts": 1363045342000, "tid": 120596, "pn": 5}}', 1363045342000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1350987-chem311', 'stk-bo5bo5', 'CHEM 311', 'info', '{"desc": "ترم 132\n\nالكتاب تغير و لكن الماتيريال 90% نفس الكتاب القديم مع تغيير أرقام الشباتر , صراحة الكتاب فيه كلام كثير والأمثلة قليلة جدا وأسئلة نهاية التشابتر المحلولة في المانيوال سولوشن قليلة وأنا بأذاكر من ملفات وورد حسن البدوي , المفروض الكورس يكون سهل لكن أسئلة المياجر صعبة مقارنة بأسئلة الكتاب وأمثلته , اللاب طوييييل وممل على الفاضي\n\nالزبدة إذا تبغى تجيب قريد عالي في هذا الكورس لا بد تكون مذاكر الأولد إكزامز .يوجد أولد إكزامز في موقع الدكتور w forner , بس لا تسحب على أسئلة الكتاب 😆", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-311-physical-chemistry-ii/120596/9", "user": "Bo5Bo5", "ts": 1397228285000, "tid": 120596, "pn": 9}}', 1397228285000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1450826-chem311', 'stk-_3111', 'CHEM 311', 'info', '{"desc": "جودة المقرر بشكل عام: متوسط الجودة\nالمواضيع التي يغطيها المقرر: ينقسم المنهج الى 3 اقسام، اول تشابترين كيميا كهربائية ليست لها علاقة تذكر بتخصص الهندسة الكيميائية، ثاني تشابترين تتكلم عن الكاينتكس وتشبه جزء بسيط في 402، الشي المهم تتعلمه في نص ساعة والباقي تمطيط ماله اي داعي (خلصت ال402 ومتأكد من كلامي) التشابتر الأخير استهبال بصراحة اسمه mass transfer! طيب عندنا مادة كاملة عن هذا الموضوع!!!!!\nالكتاب المستخدم للمقرر: سيء في الاخراج والأسئلة\nالأسئلة والأمثلة المستخدمة في المقرر: الأمثلة ممتازة، الأسئلة سيئة\nمدى فائدته في الناحية التطبيقية: محدودة\n\nفي مبالغة في رأيي في أهمية هذا المقرر وعلاقته بتخصصنا، العلاقة محدودة وفي جزئية بسيطة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-311-physical-chemistry-ii/120596/10", "user": "_3111", "ts": 1464721141000, "tid": 120596, "pn": 10}}', 1464721141000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1467023-chem311', 'stk-k_94', 'CHEM 311', 'info', '{"desc": "جودة المقرر بشكل عام\nمتوسطة\n\nالمواضيع التي يغطيها المقرر\n\nتكلم عنها اخوي chemist بالتفصيل\n\nالكتاب المستخدم للمقرر\n\nممتاز بالامثلة ولكن بعضها فيها اخطاء … الكونسبت فيه حشو كلام صعب تلاقي معلومة مفيدة\n\nالأسئلة والأمثلة المستخدمة في المقرر\n\nممتازة …\n\nمدى فائدته في الناحية التطبيقية\n\nمش مرة بس حتستفيد بالrate law ك chemical\n\n-------\n\nالمادة القريد فيها اسهل بكثييير من الاورقانك خصوصا انها MCQ وفيها اولد اكزام محلول … خذوا مع دكتور يريحكم بالترم لانه الصراحة في النهاية معظم الاسئلة بتجي مغايرة للشرح\n\nانصح بالدكتور البيطار في حال كان يدرسها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-311-physical-chemistry-ii/120596/11", "user": "K_94", "ts": 1485384475000, "tid": 120596, "pn": 11}}', 1485384475000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1467618-chem311', 'stk-user9534', 'CHEM 311', 'info', '{"desc": "الصراحة كانت أصعب كيسمتري بالنسبة لي\n\nعموماً المادة طبعاً زي الأناتيكال مالها فائدة للمهندس الكيميائي ألا بالشابتر الاخير حق الماس ترانسفير وأساساً عندنا كورس كامل للماس , rates law بتشوفها في كورسات ثانية بعدين\n\nالكتاب حق المادة سيء , ماعدا أنك تشوف الأمثة وأسئلة الواجب . أما أنك تفهم وتقرا منه صعب جدا والله\n\nهذا ملف فيه المانيوال سلوشن للكتاب + كويزات + اولد اكزامز محلول\nPhysical files - Download - 4shared\n\nالله يعينكم عليها : )", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-311-physical-chemistry-ii/120596/12", "user": "user9534", "ts": 1486247192000, "tid": 120596, "pn": 12}}', 1486247192000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p913584-chem311', 'stk-che1', 'CHEM 311', 'info', '{"desc": "نوت الداعوس ممتاز جداً … وهو موجود بالجمعية\n\nالنوت يفيدك في فهم الـ concept\n\nوعندك في السيلبوس suggested Hw problems هذه مهمة جداً ، تقريبا ١٥ سؤال على كل chapter\n\nإذا فهمت الـconcept من نوت الداعوس , وحليت الـ example الكتاب اللي غالبا الداعوس ينقله في النوت\n\nوحليت الـ suggested problems في آخر كل chapter ستشعر أن الأمور تحت السيطرة وترتاح في المادة\n\nبقيت إضافة أخيرة :::\n\nإذا لقيت مياجر قديمة لنفس الدكاترة اللي يدرسون الآن لا تفوتها لأن الداعوس يعيد الأسئلة غالباً\n\nبالنسبة لكويزات الداعوس ، هو أخبرنا أنه يأخذ من الـ suggested Hw problems ويغير فيها أرقام فقط\n\nبالتوفيق يا شباب", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem311/95973/5", "user": "CHE1", "ts": 1317794195000, "tid": 95973, "pn": 5}}', 1317794195000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p974039-chem311', 'stk-user2728', 'CHEM 311', 'info', '{"desc": "وعليكم السلام ورحمة الله وبركاته\nنوت الدكتور الداعوس يكفي كفهم للمادة وبعض المسائل\n\nوالكتاب يجي معه سلوشن مانوال حاول أسبوعيا تحل أسئلة الكتاب بغض النظر عن إنه مشار له كهمورك أو لا أهم شيء الممارسة والتعود على الحل لترسيخ المعلومة\n\nالمادة ما فيها هوموركات بس يعطونك بعض الأسئلة للمارسة والتعود على أسئة الإختبار\n\nالمذاكرة من الكتاب والأولد إكسامز ما أقدر أفيدك فيها لأن الكتاب ما أفتحه إلا لحل أسئة الكتاب والأولد إكسامز ما كان متوفر لنا وقتها", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem311/118959/2", "user": "user2728", "ts": 1327552197000, "tid": 118959, "pn": 2}}', 1327552197000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1100933-chem311', 'stk-abu_3zzoz', 'CHEM 311', 'srcP', '{"html": "^^^^^<br>سم و عذرا ( تصوير جوال ) 😦<br><br>​<span data-fid=\"stk-f1100933-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f1100933-0": {"name": "Chemist.zip", "v": "https://cyuufavrbqyqywhftbjw.supabase.co/functions/v1/api/media/7c9fe7e04a7d863f9a44fa0b45fc487928ae4789107cd68ebcdc1dc6f1001906"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/chem-311/132633/7", "user": "Abu_3zzoz", "ts": 1349005034000, "tid": 132633, "pn": 7}}', 1349005034000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bo5bo5-chem311', 'stk-bo5bo5', 'CHEM 311', 'doc', '{"docs": [{"id": "stk-dr-f68545", "n": "Dr. Mazen Khaled", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM311 Lecture - TERM132\n\nالتحضير :\nكل يوم ورقة تمر على الطلاب , إذا تأخرت ما يقول شيء\n\nطريقة الشرح :\nيقرأ من نوتاته اللي هي أصلا نسخ لصق من الكتاب , سيء في الشرح\n\nالكويزات :\nمن أسئلة الأولد إكزام , يعني صعبة , open book\n\nالمياجر:\nكومن\n\nالفاينلات :\nكومن\n\nالقريد النهائي:\nf\n\nالصوت:\nواضح\n\nإضافات :\nإذا بتنزل معاه راح تعتمد على نفسك تماما , الدكتور ما راح يفيدك في شيء", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1350974-chem311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mazen-khaled/68545/31", "user": "Bo5Bo5", "ts": 1397226479000, "tid": 68545, "pn": 31}}, {"id": "stk-dr-f68546", "n": "د. مونج", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem 311 lab - term 132\n\nالتحضير :\nعن طريق الريبورت , ما يدقق على التأخير يعني في ناس تتأخر أكثر من 10 دقايق وما يقول شيء\n\nطريقة الشرح :\nعادي على السبورة يكتب لك الخطوات\n\nالكويزات :\nلا يوجد\n\nالفاينلات :\nلا يوجد\n\nالقريد النهائي:\nc+\n\nالصوت:\nواااضح واللهجة ممتازة\n\nإضافات :\nالدكتور تحسن من ناحية الأخلاق وما شفته عصب ولا مرة طول الترم أشوفه كأنه يبغى يعصب لكن يمسك نفسه , ومشكلته أنه غير متعاون يعني إذا خلص الشرح وطلبت مساعدته أثناء التجربة يقول \"everything is clear \" فأطلب المساعدة من التقنيين , متساهل في التصحيح و الدرجة النهائية كانت بين 74.5% - 75.8% لطلاب السكشن يعني إذا نزلت عنده لا تخاف من ناحية الدرجات , أغلب الأحيان نطلع على نهاية الوقت ونادرا قبلها بنصف ساعة لأن التجارب طويلة وأيضا الريبورت يأخذ وقت\n\nلو تنزل عند د.فورنر أفضل لك لأنه ما يطلب ريبورت يطلب فقط الـ excel sheet ويطلع الطلاب بدري", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1392783-chem311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68546/25", "user": "Bo5Bo5", "ts": 1408890057000, "tid": 68546, "pn": 25}}]}', 1397226479000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4988-chem311', 'stk-user4988', 'CHEM 311', 'doc', '{"docs": [{"id": "stk-dr-f68546", "n": "د. مونج", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 311\n121\nLab\n\nبقي لنا 4 لابات ونخلص إن شاء الله\nحتى الآن الرجل أشوفه\nNot bad at all\n\nيشرح لك إيش المطلوب تسويه في اللاب ( يفضل تكتب وراه في ورقة خارحية ) ثم تسوي الإكسبيرمنت ثم تكتب الريبورت و تسلمها له فوراً\n\nتصحيحه جيد ، مو شديد و كثيرين اللي جابوا 9.5 من 10 >> هذا من اللي شفته حتى الآن ، ممكن ينقلب علينا في الأخير !!!\n\nمشكلته أخلاقه جافة إلى حد ما ، يعني لما يخلص من شرح طريقة اللاب ثم يقول :\nany questions ??\nيجي طالب يسأله في حاجة ، يقوم الدكتور يضحك و يقول :\nC’mon man , this is silly question\n\n😲\nطيب …\nإذا إنه سيلي كوسشن ، ليش تسوي لي فيها سياسة الباب المفتوح ؟؟\n\nطبعاً هذا إذا ما هزأ الطالب أصلاً ، عشان كذا أنا قلت ( يفضل تكتب وراه في ورقة خارحية ) عشان ما تضطر تسأله و ممكن تأكل تهزئة ما لها داعي …\n\nبنعود بالتفاصيل إن شاء الله نهاية السمستر أو بعدما ينزل لنا قريدات اللاب …\n\nالله يستر\n\nو بالتوفيق", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1122578-chem311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68546/18", "user": "user4988", "ts": 1353738682000, "tid": 68546, "pn": 18}}]}', 1353738682000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4656-chem311', 'stk-user4656', 'CHEM 311', 'doc', '{"docs": [{"id": "stk-dr-f68546", "n": "د. مونج", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور سيء من ناحية الاخلاق زي ماقالوا الاخوان ,\nبالنسبة للشرح عادي , يشدد في الحضور والغياب ويشدد في الكويزات\nالدكتور منظم …\nللاسف العيب الكبير هو أخلاقه للأسف تجارية جدا ً جدا جدا ً\nالمادة chem 311", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1162310-chem311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/68546/20", "user": "user4656", "ts": 1357922560000, "tid": 68546, "pn": 20}}]}', 1357922560000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chemist-chem311', 'stk-chemist', 'CHEM 311', 'doc', '{"docs": [{"id": "stk-dr-f68547", "n": "Dr. Mohamed Morsy", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 311 LEC Term 121\n\nالتحضير:\nحسب المزاج اذا اشتهى حضر واذا مااشتهى ماحضر 🤠 بس في وجهة نظري اعتقد انه يحضر كذا يعني مايهتم بتحضير وشكله على قولة أخوي شامخ يعرف من يحضر ومن لا يحضر\n\nالشرح:\nكدت اطير من الفرح لما نزلت معه 311 ولكن انصدمت بخيبة أمل 😭 شرح ممل لدرجة ماتتوقعها والكلاس نايم من شرحه عدا كم طالب. هذا الدكتور يذكرك بأيام الثانوية بحيث ان شرحه من خلال السبورة. تخيل طول الحصة يكتب ويردد اللي يكتبه قمة في الملل. بس اذا نزل الطبشورة أبشر بعزك والله يطلع لك انسان ثاني ويكون شرحه ممتع.\n\nنوته اللي يكتبه على السبورة هو الكتاب نفسه بل الكتاب أفضل منه حيث ان المعلومات في نوته غير كافيه\n\nالكويزات:\nغالبا سهلة ومن المياجر القديمة او من الكتاب ما اذكر انه قيد جاب من برا\n\nمميزات الدكتور:\n1) روعة في الأخلاق والتعامل والتواضع\n2) يهتم لطالب بشكل كبير ويهتم بمصلحته\n\nعيوب الدكتور:\n1) شرحه كما أسلفت\n2) مايتواصل على الكومبيوتر ابد ولا يعرف شي اسمه ويب سيتي ولا شي 😞\n3) دايما يتأخر في انهاء المحاضرة وهذا سبب لي احراج مع الدكتور اللي بعده 😞\n\nالقريد النهائي:\nأعطيه +C", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1166200-chem311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-morsy/68547/20", "user": "Chemist", "ts": 1358614672000, "tid": 68547, "pn": 20}}, {"id": "stk-dr-f69110", "n": "Dr. W Forner", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 311 Lab Term 121\n\nالتحضير:\nيتأخرون الشباب مايقول شي بس في بعض المرات يعصب شوي. في يوم من الأيام وأن دايما أجي بدري 7:40 من الإجتهاد 😁 جيت متأخر دقيقتين حط علي سالفه وقام يصرخ ويخانق كني ذابح أحد من أهله والله انها فولت معي وبغيت أرد عليه لكن مشيتها وبعد هالموقف السخيف منه كرهته\n\nالشرح:\nزفت وأزفت من الزفت لدرجة اني في بعض الأحيان أكون فاهم التجربة ولكن لما يشرحها تضيع المعلومات اللي في راسي 😞\n\nأخلاقه:\nزفت ويرد عليك بنفس خايسه. مالك إلا سؤال واحد يرد عليك بشكل طبيعي وبعد كذا اذا سئلته أي سؤال يعصب ويقول انا قيد شرحتها وانت مانت منتبه وقد كتبتها على السبورة. أنا عن نفسي ما عاد أسئله واعتمد على الله ثم على نفسي.\n\nمميزاته:\nفيه ميزه كبيره انه مايدقق في تصحيح الريبورت ومسهل عليك كتابة الريبورت ودرجاته عاليه في الريبورتات اذكر اقل ريبورت أخذت فيه 8 من 10 👍 والباقي أكثرها 9 من 10\n\nالكويزات:\nمافيه\n\nالقريد النهائي:\nأعطيه D الأخلاق قبل كل شي", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1166222-chem311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/w-forner/69110/19", "user": "Chemist", "ts": 1358618372000, "tid": 69110, "pn": 19}}]}', 1358614672000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-way_to_aim-chem311', 'stk-way_to_aim', 'CHEM 311', 'doc', '{"docs": [{"id": "stk-dr-f68547", "n": "Dr. Mohamed Morsy", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "chem 311\n\nتحضير :نادر جدا\n\nالشرح:\nنوت على السبورة\nشرحة نظري ( ما يحل امثلة إلا قليل جدا ) دائما يقول بحل لكم أمثلة و لا يحل\nباستثناء بعد الاوقات يحل الكوزات ( مب كل الكوزات)\n\nالكوزات:\nمن الاولد اقزام.\n\nالكلاس ورك:\nدرجاتك في الكوزات.\n\nحضر مرة الدكتور الدعوس بداله ما في أي مقارنة, الدعوس أفضل منه بمليون مرة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1227212-chem311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-morsy/68547/29", "user": "way_to_aim", "ts": 1369404715000, "tid": 68547, "pn": 29}}]}', 1369404715000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9305-chem311', 'stk-user9305', 'CHEM 311', 'doc', '{"docs": [{"id": "stk-dr-f68547", "n": "Dr. Mohamed Morsy", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 311 (Physical Chemistry II) - Term 151 Lec\n\nالتحضير:\nبالإسم يومياً، وقليل ينسى.\n\nطريقة الشرح:\nالشرح ممتاز، الإنجليزية متوسطة ويكتب كل شيء عالسبورة.\n\nالكويزات:\nمتوسطات المستوى، وحذف واحد او اثنين في آخر الترم.\n\nالمياجر:\n- ميجر 1 سهل، الآفرج ان ما خاب ظني كان في حدود الـ 68-70.\n- ميجر 2 صعب بشكل كبير، الآفرج كان قريب من الـ 50، الأسئلة جائت بطريقة مختلفة تماماً عن الأترام السابقة.\n\nالفاينل:\nمتوسط مائل للسهولة.\n\nالصوت:\nواضح جداً.\n\nإضافات:\n- الدكتور مرح وطيب القلب وكلاسه ما تحس بالملل الكبير فيه.\n\n- ساعته متأخرة كم دقيقة، وفي كل مرة ياخذ 2 او 3 دقائق زيادة بحجة ان وقت المحاضرة حسب ساعته ما انتهى :).\n\nالقريد النهائي:\nB+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1451564-chem311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-morsy/68547/33", "user": "user9305", "ts": 1465734304000, "tid": 68547, "pn": 33}}]}', 1465734304000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-k_94-chem311', 'stk-k_94', 'CHEM 311', 'doc', '{"docs": [{"id": "stk-dr-f68547", "n": "Dr. Mohamed Morsy", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 311 -Term 161\n\nالتحضير : نااااادر يحضر الطلاب , اخر اسبوع قال لنا باحضر الاسبوع كله لازم تجون , حضر الاحد وباقي الايام سيفون 😅\n\nطريقة الشرح : جدا مملة وغير مناسبة لي , نااااادر يحل اسئلة ومعظم شرحه نظري كيف اشتقينا القانون الفلاني ( المشكلة القانون النهائي موجود !! ) وكيف جت النظرية الفلانية , بعض الناس يفضل الطريقة هذي لكن مو انا\n\nالكويزات : صعبه يجيبها من اولد اكزام وبعض الكوزات يجيبها MCQ ولكن اذا ما كتبت الحل يعطيك 0 حتى لو اجابتك صح\n\nالمياجر: سهله نوعا ما الافرج حق الميجرين حول 67%\n\nالفاينلات : حرييييقه طلعوا الافرج العالي حق المياجر من عيوننا 😭\n\nالصوت: واضح ومفهوم\n\nإضافات : الدكتور مرسي قبل ما اسجل عنده كنت اسمع عنه اسطورة بالشرح ولكن للاسف طلع ما يناسبني نهائيا وكوزاته صعبه عكس باقي الدكاتره , وما يعطي يوم off بعد الميجر الا بالمذله ويقول لا تقعد تقول لي الدكتور الفلاني اعطى وانت لا … عطانا اوف لميجر 1 بس\n\nالدكتور ما يسوى تنزل عنده يكفيك هو الوحيد اللي اعطانا Hw و take home quiz والوضع ما يسوى لانك حتذاكر للمياجر من الاولد اكزام وتستفيد منها اكثر من هومووركاته … بعض الtake home quiz كان يطلب منا نشتق القوانين اللي بالكتاب !! 😠", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1467022-chem311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-morsy/68547/34", "user": "K_94", "ts": 1485384167000, "tid": 68547, "pn": 34}}]}', 1485384167000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmed1-chem311', 'stk-ahmed1', 'CHEM 311', 'doc', '{"docs": [{"id": "stk-dr-f68547", "n": "Dr. Mohamed Morsy", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 311 -Term 222\n\nالتحضير : احيانا يحضر و احيانا لا بس غالبا يحضر، التحضير في بداية الكلاس وما عنده مشكلة لو جيت متأخر يحضرك بعد الكلاس.\n\nالشرح : يشرح من سلايداته (شوي مب مرتبة بس ممتازة) ويحل بعض الاسئلة من الاولد او الكتاب عشان توضح الفكرة زيادة. اشوف شرحه ومقاطعه المسجلة افضل مصادرك للمادة بالإضافة الى اسئلة نهاية كل شابترز\n\nالكويزات : صعبة الله حق، يجيب من الأولد او الكتاب ويعدل عليها، خذنا 5 كويزات واخر كم كويز كانوا تيك هوم كويز، بالمناسبة نادر احد ياخذ فل في كويزاته فذاكر عدل لها.\n\nالمياجر: كومن وصعبة والافرج فيهم اثنينهم ما تعدى ال 50%\n\nالفاينلات : كومن وكان تافه وتعويض مباشر والافرج 78%\n\nالتقييم النهائي:\nA\n\nالصوت: واضح ومفهوم ولغته ممتازة.\nإضافات : الدكتور محترم جدا جدا وخفيف دمه وعلى ان المادة كريهة الا انه يحاول يخلي الكلاس لطيف على الطلاب بمزحه وابتسامته الدائمة الله يعطيه العافية.\n\nبالنسبة للمادة انصح الجميع بالمذاكرة من مقاطع دكتور مرسي في حال ما قدرت تنزل عنده وتحل اسئلة نهاية الكتاب، لا تركز على الاولد بشكل كبير لانهم يجيبون اسئلة جديدة. المادة في ظاهرها انها صعبة واختباراتها صعبة بس توزيع القريدات ممتاز وتقدر تحصل قريد حلو فيها.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536739-chem311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohamed-morsy/68547/36", "user": "Ahmed1", "ts": 1686156490000, "tid": 68547, "pn": 36}}]}', 1686156490000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user4221-chem311', 'stk-user4221', 'CHEM 311', 'doc', '{"docs": [{"id": "stk-dr-f69110", "n": "Dr. W Forner", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السلام عليكم\n\nبصراحة أنا عند المدرس في الفصل الحالي Chem311,\n\nالشرح: سيء\n\nطريقة الشرح : سلايدات يقرأها باستخدام البروجكتور.\n\nالكويزات : متوسطة إلى سهلة ( أسئلة محددة من المانيوال سولوشن ).\n\nالصوت: جيد و لكنته رائعة.\n\nالتحضير : ورقة تمر على الطلاب يسميها هو (Book of Lies), لأن ما يحضر عنده إلا نصف الفصل والنصف الباقي ساحبين و يحضرونهم زملائهم, و لو أتيت بعد (ثلث,نصف) ساعة أو أكثر و لا كأن شيئاً حصل ;يقول (“Lucky you I don’t care”).\n\nالمياجر: كومون ( اختيار متعدد).\n\nالتقييم : c\n\nملاحظة في اللاب أفضل منه في الحصة , و يتساعد معك في قضية التقارير , أتذكر مرة كان علينا ميجر 1 لل Chem 311 في نفس يوم اللاب ,ققال طلابي ليسوا بحاجة إلى أن يعطوني ( pre-report) ولا الرسم و لا حتى بيانات التجربة, فقط أنهوا التجربة و اذهبوا و سلموا لي المطلوب الأسبوع القادم.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p610245-chem311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/w-forner/69110/12", "user": "user4221", "ts": 1274201030000, "tid": 69110, "pn": 12}}]}', 1274201030000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user6661-chem311', 'stk-user6661', 'CHEM 311', 'doc', '{"docs": [{"id": "stk-dr-f69110", "n": "Dr. W Forner", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Chem 311 - الترم 111\n\nأنحححححححححححححش !!!!!!\n\nفر منه كفرارك من الأسد !!!\n\nشرح مييييييح بكل ما تعنيه الكلمة من معنى …\n\nآفرج سكشنه دائما اقل من باقي الدكاترة (وبفارق كبيـر) …\n\nطريقة الجشح على بروجيكتر قديم (ابو ورق شفاف) وما يمديك تقرا شي !!!!\n\nبالنسبة للتحضير ورقة وتمر عالطلاب ويمديك تحضر اخوياك وتحضر ابناء الدول المجاورة اذا تبي بعد !!\n\nبالنسبة للكويزات يجيبها كوبي بييييست من الهوموورك وبالأرقام …\n\nوالشعب كانوا يصورون السليوشن بجوالاتهم وينقلونها (كوبي بيست) على ورقة الإختبار …\n\nونتايج الكويز اكثر من نص الكلاس ماخذ (10 من 10) …\n\nالمياجر والفاينل (كومون)\n\nالدكتور اخلاقه جدا سيئة مع الطالب في المحاضرة ولكن في المكتب تعامله يختلف كثير …\n\nبإختصار هالكورس لا تفكر ولو مجرد تفكير انه تنزل مع هالفورنر !!!\n\nأنحححححش !!!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p971391-chem311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/w-forner/69110/17", "user": "user6661", "ts": 1327104772000, "tid": 69110, "pn": 17}}]}', 1327104772000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2728-chem311', 'stk-user2728', 'CHEM 311', 'doc', '{"docs": [{"id": "stk-dr-f118614", "n": "د. محمد الداعوس", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 311- Lab\n\nالتحضير :\nعلى الريبورت\nطريقة الشرح :\nيهتم بالثيوري ويعلمك الهدف من التجربة ويشتق لك المعادلات المطلوبة ويحط لك الثوابت المطلوبة للمقارنة والحساب\nبس ما يعلمك التجربة لأن إللي يعلمك إياها هو واحد ثاني هندي مسؤول عن اللاب يسوي التجربة قدامك ويعلمك إيش الخطوات العملية\nمشكلتها الأرقام كثيرة والحجوم والفلاسكات تضيع بينها فتتلخبط في الخطوات حقت التجربة\nعموما كفهم وتجربة تقييمي للشرح بيكون ممتاز\n\nالكويزات :\nيطلب بري لاب على كل تجربة\nالبري لاب هو أنك تكتب الإنترودكشن والاوبجكتف عن التجربة إللي جاي لها عشان تطبقها\nأول السمستر كان يطلب بعدين وقف في النص بعد ما لحوا عليه الطلاب\n\nالمياجر:\nما فيه\n\nالفاينلات :\nما فيه\n\nالقريد النهائي:\na+\n\nالصوت:\nواضح\n\nإضافات :\nعادة يتكلم عربي والطلاب يتكلمون معه عربي ويسولفون معه ويتجاوب معهم\n\nعادة ما راح تحصل درجة كاملة في الريبورتات لأنه كلها حول ال 7 من 10 وما تعرف بالضبط إيش الخطأ\nفي النهاية هي أفرج والقريدات متساوية\n\nالريبورتات يسمح بعض الحيان بتأخير تسليمها\n\nالتجربة كل اثنين مع بعض\nوخلص التجربة وأمش وكمل الريبورت في الغرفة\nواثنينكم تسلمون ريبورت واحد وأنتوا تتفاهمون مع بعضكم مين يسلم والتقييم بيكون متساوي على الإثنين\n\n🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p972173-chem311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/118614/3", "user": "user2728", "ts": 1327261440000, "tid": 118614, "pn": 3}}]}', 1327261440000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abo_fauzi-chem311', 'stk-abo_fauzi', 'CHEM 311', 'doc', '{"docs": [{"id": "stk-dr-f152614", "n": "Dr. A Al-Betar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM 311 - Term 162\n\nالتحضير : يومياً ورقة تمر على الطلاب تكتب فيها اسمك بالعربي ! 😐\n\nطريقة الشرح : مملة جداً … للأمانة الدكتور باين عليه فاهم المادة مزبوووووط لكن بسبب نبرة صوته وتركيزه عالكونسبيت بشكل مررررة كبير فالكلاس يكون جداً ممل … الدكتور الله يهديه لو يركز على حل المسائل زي ما يركز عالكونسبت يكون شيء ممتاز لأنو أغلب الميجر يكون مسائل لكن بسبب طريقة شرحه فالبقوة تقدر تركز معاه في الكلاس\n\nالكويزات : متوسطة المستوى وتصحيحه فيها دمار … خطأ بسيط حتى لو حلك صح عادي يعطيك ثلث درجة السؤال\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: C\n\nالصوت: نبرة وحدة تجيب النوم\n\nإضافات :\n- الدكتور لمن يجي يتكلم معاك يحسسك انك عايش في عالم ثاني … ميجر 1 وميجر 2 كان فيه أخطاء في وضع الأسئلة , لمن الشباب أتناقشوا معاه بعد ميجر 2 قالهم انتوا لازم تتعلموا من أخطائكم وما تضيعوا وقت على سؤال ما تعرفوا تحلوه … طيب يا حبيبي ليش ما انتوا تتعلموا من أخطائكم وتراجعوا الأسئلة اللي تحطوها قبل الاختبار !! 😠", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1474259-chem311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-al-betar/152614/8", "user": "Abo_Fauzi", "ts": 1496263831000, "tid": 152614, "pn": 8}}]}', 1496263831000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a-alajmi-chem311', 'stk-a-alajmi', 'CHEM 311', 'doc', '{"docs": [{"id": "stk-dr-f175794", "n": "Dr. Mohammad Janjua", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "172 LAB Chem 311\nالتحضير : الساعة 1:00 لازم تكون في لالاب ويمشي التأخير في بعض الأحيان\nطريقة الشرح : على السبورة ويفصل التجربة تفصيل ودائما يقول I am trying to make your life easy\nالكويزات :لا يوجد\nالمياجر: لا يوجد\nالفاينلات : لا يوجد\nالقريد النهائي: A+\nالصوت: واضح ومفهوم\nإضافات : الدكتور حبيب ومتعاون ويمشي اللاب سهالات , انصح فيه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1491391-chem311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-janjua/175794/17", "user": "A-Alajmi", "ts": 1524568722000, "tid": 175794, "pn": 17}}]}', 1524568722000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-alharthi999-chem311', 'stk-alharthi999', 'CHEM 311', 'doc', '{"docs": [{"id": "stk-dr-f175794", "n": "Dr. Mohammad Janjua", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "term172 chem311 LAB\n\nالتحضير : لازم تكون موجود قبل ما يبدا اللاب ويمشي بعض الاحيان التاخير البسيط وينتظر المتاخرين عادة عشان يحرجهم وهم داخلين انكم اخرتوا اخوياكم ولا بدينا 😆 😆\nطريقة الشرح : يفصل في شرح التجربة وبعض الاحيان تكون مملة لان فيه حاجات سهله ويطول فيها وعرفنا بعدين ليش عشان ما نطلع بسرعه 🚬 😆 😆… بس حلو شرحه وفيه حس الدعابة\nالكويزات : لا يوجد\nالمياجر:لا يوجد\nالفاينلات : لا يوجد\nالقريد النهائي: A\nالصوت: واضح والاكسنت الباكستاني موجود\nإضافات : دكتور حبييييييب وطييييب جدا جدا جدا … ويحسسك انك صديق له او اخ ما يبي يحسس الطالب ان انا دكتور ولازم بيننا حواجز … كثير احيان نطلبه نبي نطلع بدري اليوم عشان المياجر وكذا وما يقصر يقول ابد سوو الي تقدرون عليه والله يستر عليكم … انصح فيه وبقوه 🌹 🌹 🌹", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498285-chem311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-janjua/175794/19", "user": "alharthi999", "ts": 1535462561000, "tid": 175794, "pn": 19}}]}', 1535462561000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mahmo0od-chem311', 'stk-mahmo0od', 'CHEM 311', 'doc', '{"docs": [{"id": "stk-dr-f175794", "n": "Dr. Mohammad Janjua", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سمستر 182 - CHEM311\n\nLeacture & Lab\n\nالتحضير : يحضر بكل كلاس\nطريقة الشرح : طريقة شرح الدكتور من السلايدات وبعض الاحيان يشرح على السبورة اذا احتاج\nالكويزات : عددها معقول ومستواها متوسط وككلها كانت مفيدة ومهمة للميجر\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: جدا واضح ومفهوم ومو نفس باقي الاجانب\nإضافات: وصلنا للجزئية المهمة، الدكتور جدا جدا جدا جدا حبيب ومتساعد ومتفهم لاي ظرف ممكن يحصل لك.\n\nمادة الفزكل كمستري معروف انها من اصعب المواد ولكن الدكتور يحاول بكل م يقدر انه يخففها ويسهلها بالي يقدر عليه.\n\nبالنسبة للاب، اخف واجمل لاب مر علي بالجامعه، مع ان لاب الفزكل يعتبر واحد من الاسوء !!\n\nبالمختصر جو الكلاس واللاب ضحك وفلة وسواليف + محاضرة عن الكيمياء\n\nنزل اي مادة عن دكتور جنجوا وانت مغمض ومستانس ومرتاح وحتى بنهاية الكورس بالنسبة للكلاس ورك لا تشيل هم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1508958-chem311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-janjua/175794/20", "user": "mahmo0od", "ts": 1556175934000, "tid": 175794, "pn": 20}}]}', 1556175934000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ammarda-chem311', 'stk-ammarda', 'CHEM 311', 'doc', '{"docs": [{"id": "stk-dr-f175794", "n": "Dr. Mohammad Janjua", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "سمستر 182 - CHEM311\n\nLecture\n\nالتحضير : يحضر بكل كلاس بورقة، بس ينتبه للي يحضرون بعص\nطريقة الشرح : المادة تعبانة أصلا والشرح فيه صعب ولكن الدكتور يحاول اللي يقدر عليه ويحاول يبسط الكونسبت\nالكويزات : قليلة وسهلة والحلو أنه يكون فيها كونسبت مهم للمياجر.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي : A+\nالصوت: مسموع والاكسنت كويس ،و الدكتور يخلي الكلاس حبي ويطقطق ويسوي إنطباعات جميلة بصوته. الدكتور حبيب جدا ومتساعد.\n\nبالاخير المشاكل اللي كانت موجودة كانت مع المادة مو مع الدكتور.\n\nالدكتور يريحك ولا يتعبك ويحاول يبسط المادة قد ما يقدر، والكلاس ورك معه مفروغ منه. لا تتوقع فهم عنده بس توقع راحة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1508960-chem311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-janjua/175794/21", "user": "Ammarda", "ts": 1556177699000, "tid": 175794, "pn": 21}}]}', 1556177699000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulrahman_ar-chem311', 'stk-abdulrahman_ar', 'CHEM 311', 'doc', '{"docs": [{"id": "stk-dr-f175794", "n": "Dr. Mohammad Janjua", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM311: 182\nLecture\n\nالتحضير : يحضر بكل كلاس عن طريق ورقة يمررها على الطلاب بسبب ثقته بالطلاب فيتضايق لما احد يحضر خويه، لأنه قال لو عندك أي سبب للغياب علمني وبتساهل معك وكان صادق بكلامه تساعد معي بسبب غيابي.\nطريقة الشرح : يشرح عن طريق سلايدات وإذا كان يحتاج توضيح يكتب على السبورة بس المادة بشكل عام تحتاج تركيز كبير، يعني لا تتوقع الشرح بيغنيك بشكل كبير.\nالكويزات : تكون تركز بشكل كبير على فهمك لمحتوى المياجر يعني لما تحلها زين تبدع بالميجر.\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: ممتاز والنطق واضح وما بتلقى صعوبة في فهمه\nإضافات: الدكتور أخلاقه جداً ممتازة وما بتندم انك نزلت المادة معه كان متساهل ومتساعد ودايم بصف الطلاب، وبحكم انه كوردنيتور حاول يغير ترتيب المنهج وترك جزيئة الكوانتوم بالنهاية عشان يكون عندك وقت تذاكرها زين.\n\nباختصار الدكتور ممتاز من نواحي كثيرة.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1508966-chem311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-janjua/175794/22", "user": "Abdulrahman_AR", "ts": 1556189693000, "tid": 175794, "pn": 22}}]}', 1556189693000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saad_sulaiman-chem311', 'stk-saad_sulaiman', 'CHEM 311', 'doc', '{"docs": [{"id": "stk-dr-f175794", "n": "Dr. Mohammad Janjua", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "182 - CHEM 311\n\nالتحضير : ورقة تمر على الطلاب و معطي الثقة للطلاب لكن يقفط اللي يحاول يوقع لغيره لأنه يعرف كل الطلاب بأسماءهم\nطريقة الشرح : من السلايدات اللي هو مسويها ويكتب على السبورة اذا احتاج ويربط المعلومات والكونسبت بأمثلة من واقع الحياة تخليك ما تنساها وأحيانا يعطيك أمثلة تضحك وتفهم بنفس الوقت\nالكويزات : الكوزات سهله غالباً إلى متوسطة\nالمياجر: كومن\nالفاينلات : كومن\nالقريد النهائي: A+\nالصوت: واضح جداً جداً صوتاً ولغةً\nإضافات : الدكتور جداً متعاون ومرن من ناحية الكوزات ويقدر إذا كان فيه ضغط خصوصاً بفترة المياجر ويشاورنا على وقت الكويز. أيضاً متعاون ومقدر للطلاب اللي عندهم ظروف بالنسبة للغياب. مرح وله أسلوبه الخاص بالكلاس اللي يخليك تحبه ولا تحس بوقت الكلاس لأنه متى ما حس أن الطلاب فصلوا يعطيهم نكت وكذا ويرجع للشرح. عنده شيء مضحك ومميز بنفس الوقت اللي هو إذا تأخر الطالب يقول له يا أكتب لك ليت ولا تجيب شوكلاته أو عصير لكل الكلاس المرة الجاية D=. اللاب دائماً عنده سريع لأنه يعطيك الزبدة وتصحيحه للريبورتات جيد وبالنهاية نورملايزاشن أعلى واحد 76 وأقل واحد 74.\nما أقول الله يجزاه خير كان مسهل علينا صعوبة الفيزيكال\nالزبدة: إذا شفته نزززززل بدون ما تشاور أحد لأنه إنسان عظيم قبل ما يكون دكتور عظيم!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1509039-chem311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-janjua/175794/23", "user": "Saad_Sulaiman", "ts": 1556314725000, "tid": 175794, "pn": 23}}]}', 1556314725000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-moe_baqais-chem311', 'stk-moe_baqais', 'CHEM 311', 'doc', '{"docs": [{"id": "stk-dr-f175794", "n": "Dr. Mohammad Janjua", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CHEM-311 Lab / Term 211\n\nبنود التقييم :\n\nالتحضير : ما يحب التاخير، مايحاسب عليه بس يكلم الطلاب بطريقه لطيفه تخليك تحضر دايم عالوقت، مثلا اذا اتاخرت يقولك المره الجايه اذا اتاخرت لازم تجيبلنا معاك دونات او علبة شوكلاته.\n\nطريقة الشرح : كان يشرح التجربه بشكل مبسط بحيث مايضيعك بالدرفيشن حق القوانين والاشياء اللي مالها داعي. ويشرحلك بالضبط ايش الاشياء اللي مطلوب تسويها بالريبورت. بشكل عام كان جدااا مسهّل الأمور وكان مخلي اللاب فعلا تجي تستمتع فيه ولا تشيل هم ابدا.\n\nالكويزات : ماكان في كويزات.\n\nالفاينلات : الفاينل لاب كان كومون.\n\nالقريد النهائي: الدكتور اعطيه A+ ولو في شي اعلى كان اعطيته.\n\nالصوت: واضح جدا والاكسنت مفهوم.\n\nإضافات : الدكتور جدا حبيب، اخلاق ومتعاون، دمه خفيف ويحب يمزح مع الطلاب في اللاب ويخلي الجو لطيف ومافيه اي رسميات ابدا. باختصار افضل دكتور لاب درسني، والحمدلله اني درست عنده في اخر مادة كمستري لي في الجامعه.\n\nThank you Dr. Janjua ❤️", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533201-chem311", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mohammad-janjua/175794/28", "user": "Moe_Baqais", "ts": 1640766468000, "tid": 175794, "pn": 28}}]}', 1640766468000, 1794826848, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
